// 🧹 CLEAN DATA FOR AI
// Remove biasing metadata (type, section, etc) to prevent AI from grouping links.

const items = $input.all();
const results = [];

for (const item of items) {
    const content = item.json.content;
    const rawLinks = item.json.links || [];

    // Keep ONLY essential fields for the AI
    const cleanLinks = rawLinks.map(link => ({
        claim: link.claim,
        anchor: link.anchor,
        url: link.url
    }));

    results.push({
        json: {
            content,
            links: cleanLinks
        }
    });
}

return results;
